WITH exploded AS (SELECT id, effective_from, currency, EXPLODE(discounts) AS element FROM price_tiers) SELECT *, DENSE_RANK() OVER (PARTITION BY currency ORDER BY element DESC NULLS LAST) AS element_dense_rank, DENSE_RANK() OVER (PARTITION BY currency ORDER BY element) AS element_dense_rank_2, MIN(element) OVER w_recent AS currency_min_element, COUNT(element) OVER w_recent AS currency_count_element FROM exploded WINDOW w_recent AS (PARTITION BY currency);
